using UnityEngine;
public class FadeVisual : MonoBehaviour
{
    private float remaining = 0.5f;
    private void OnEnable()
    {
        GetComponent<Animator>().SetTrigger("Signal");
    }
    private void Update()
    {
        remaining -= Time.unscaledDeltaTime;
        if (remaining <= 0f) Destroy(gameObject);
    }
}

